pub struct ExportWorkUseCase {
    uow_factory: Box<dyn ExportWorkUnitOfWorkFactoryTrait>,
    dto: ExportWorkDto,
}

impl ExportWorkUseCase {
    pub fn new(
        uow_factory: Box<dyn ExportWorkUnitOfWorkFactoryTrait>,
        dto: &ExportWorkDto,
    ) -> Self {
        ExportWorkUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for ExportWorkUseCase {
    type Output = ExportResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        progress_callback(OperationProgress::new(0.0, Some("Starting…".to_string())));

        let uow = self.uow_factory.create();
        uow.begin_transaction()?;
        // Capture the outcome, then ALWAYS close the transaction before propagating: the
        // frozen read snapshot must be released even on error.
        let outcome = run_export(&*uow, &self.dto, &progress_callback, &cancel_flag);
        uow.end_transaction()?;

        let (work_id, result) = outcome?;
        uow.publish_export_work_event(vec![work_id], None);
        progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
        Ok(result)
    }
}

fn run_export(
    uow: &dyn ExportWorkUnitOfWorkTrait,
    dto: &ExportWorkDto,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, ExportResultDto)> {
    // `gather` reads exactly `dto.work_id` — the Work to export, named explicitly.
    let g = gather(uow, dto.work_id as EntityId, progress, cancel)?;
    let work_id = g.work.id;

    let items = skribisto_compiler::item_metas(&g);
    let include = resolve_include(dto, &items)?;

    // The style travels as JSON so its schema stays owned by `skribisto_compiler`.
    let preset: skribisto_compiler::Preset =
        serde_json::from_str(&dto.preset_json).map_err(|e| anyhow!("invalid export style: {e}"))?;

    // The compiler renders in one language: the primary. Resolved here, at the boundary,
    // rather than leaving a list to be flattened somewhere downstream.
    let work_lang = skribisto_model::language::primary(&g.work.dict_language).to_string();
    // An explicit selection (Export Scene / Export Note, or the Choose… checkbox tree) keeps
    // note items regardless of the preset's `include_notes`; a swept structural scope honours
    // the toggle.
    let explicit_selection = matches!(
        dto.scope_kind,
        ExportScopeKind::CurrentScene | ExportScopeKind::CurrentNote | ExportScopeKind::Custom
    );
    let req = skribisto_compiler::RenderRequest {
        media_dir: std::path::Path::new(&dto.media_dir),
        gathered: &g,
        include: &include,
        preset: &preset,
        format: map_format(&dto.format),
        work_lang: &work_lang,
        explicit_selection,
    };

    // gather already reported up to ~90 %; map the renderer's 0..1 into the final 90..100.
    let render_progress = |p: f32| {
        progress(OperationProgress::new(
            90.0 + 10.0 * p,
            Some("Writing…".to_string()),
        ))
    };
    let path = std::path::Path::new(&dto.output_path);
    // Flatten to the full `{:#}` chain so the failure toast keeps the root cause.
    let stats = skribisto_compiler::render_to_file(&req, path, &render_progress, cancel)
        .map_err(|e| anyhow!("{e:#}"))?;

    Ok((
        work_id,
        ExportResultDto {
            exported_count: stats.items as i64,
            output_path: dto.output_path.clone(),
            comments_written: stats.comments_written as i64,
            comments_orphaned: stats.comments_orphaned as i64,
        },
    ))
}

/// The ordered ids to include: the Choose… set for `Custom`, else the quick scope resolved
/// against the frozen tree from the anchor (the first `binder_item_ids` entry).
fn resolve_include(dto: &ExportWorkDto, items: &[ItemMeta]) -> Result<Vec<u64>> {
    if dto.scope_kind == ExportScopeKind::Custom {
        return Ok(dto.binder_item_ids.iter().map(|&i| i as u64).collect());
    }
    let anchor = dto.binder_item_ids.first().copied().unwrap_or(0) as u64;
    let pos = items
        .iter()
        .position(|m| m.id == anchor)
        .ok_or_else(|| anyhow!("the item to export is not in this project"))?;
    resolve_scope(items, pos, map_scope(&dto.scope_kind))
        .ok_or_else(|| anyhow!("nothing to export for this selection"))
}

fn map_scope(k: &ExportScopeKind) -> ScopeKind {
    match k {
        ExportScopeKind::CurrentBook => ScopeKind::Book,
        ExportScopeKind::CurrentPart => ScopeKind::Part,
        ExportScopeKind::CurrentChapter => ScopeKind::Chapter,
        ExportScopeKind::CurrentScene => ScopeKind::Scene,
        ExportScopeKind::CurrentNote => ScopeKind::Note,
        ExportScopeKind::CurrentParatext => ScopeKind::Paratext,
        ExportScopeKind::CurrentFolder => ScopeKind::Folder,
        ExportScopeKind::Custom => ScopeKind::Custom,
    }
}

fn map_format(f: &ExportFormat) -> skribisto_compiler::ExportFormat {
    use skribisto_compiler::ExportFormat as C;
    match f {
        ExportFormat::Djot => C::Djot,
        ExportFormat::PlainText => C::PlainText,
        ExportFormat::Markdown => C::Markdown,
        ExportFormat::Html => C::Html,
        ExportFormat::Latex => C::Latex,
        ExportFormat::Docx => C::Docx,
        ExportFormat::Odt => C::Odt,
        ExportFormat::Epub => C::Epub,
        ExportFormat::Pdf => C::Pdf,
    }
}
